    c = getfield(asils.models.de440.de440_constants(), 'c');
    rn = sqrt(r(1)*r(1) + r(2)*r(2) + r(3)*r(3));
    k = (((1 + gamma) * mu) / ((c * c) * asils.pc.pow_(rn, 3)));
    rxv = [r(2)*v(3) - r(3)*v(2); r(3)*v(1) - r(1)*v(3); r(1)*v(2) - r(2)*v(1)];
